INSERT INTO public.content_entries ("Id", "Type", "Slug", "Title", "Data", "IsPublished", "SortOrder", "UpdatedAtUtc", "UpdatedBy") VALUES ('158629ba-9a62-4a18-8024-820eaed77442', 'project', 'provincial-hmis', 'Provincial Healthcare Management Information System (HMIS)', '{"slug":"provincial-hmis","title":"Provincial Healthcare Management Information System (HMIS)","pillar":"platforms","status":"operational","featured":true,"context":"Provincial public-health programme. Project vision, solution design and development leadership: Abid Ghaffar and Muhammad Arfan.","summary":"An AI-enabled, three-tier provincial health information ecosystem that connects primary and secondary facilities, district data hubs and a secure provincial core around a unified longitudinal patient record.","challenge":"Healthcare is information-intensive, yet patient information is often fragmented across facilities and departments — leaving clinicians with incomplete histories and managers with limited visibility for planning, surveillance and resource allocation.","solution":["Tier 1 — health facilities (DHQ/THQ hospitals and primary-care units) capture registration, queue, triage, nursing, EMR, inpatient, referral and specialty workflows.","Tier 2 — district data hubs consolidate facility data for local administration and localised reporting.","Tier 3 — a secure provincial core hosts the central patient database, embedded AI services, logistics and supply chain, FlexiCare workforce management and the patient mobile-app server, with an interoperability hub for authorised exchange.","A connected diagnostic chain links laboratory, blood bank, radiology (RIS) and PACS, with blood-product traceability from donor to bedside.","Standards-based terminology and exchange: ICD-11, SNOMED CT, LOINC, RxNorm, ICHI, ICPC-2 and HL7/FHIR.","AI is a decision-support layer — identity and registration support, clinical dictation, imaging and ECG assistance, preventive screening, medication-safety alerts, document scanning and ICD-11 disease-surveillance analytics — with clinicians remaining accountable for clinical decisions.","Security design statements include AES-256 encryption at rest, TLS 1.2+ in transit, role-based least-privilege access and audit trails. A zero-new-hardware device strategy supports existing computers, smartphones and low-cost Android tablets.","Delivered in a record four months by a small development team using an AI-driven software-delivery approach."],"capabilities":["Longitudinal patient record","CNIC-based registration","LIS · RIS · PACS · Blood bank","Maternal, child & preventive health","Workforce & payroll","Pharmacy & supply chain","Patient mobile app (Urdu/Punjabi voice booking)","ICD-11 disease surveillance","Executive dashboards","Governed AI services"],"reported":[{"label":"Sites","value":"2,000+","note":"Reported operational footprint"},{"label":"Hospitals","value":"167","note":"Hospital footprint in the technical description"},{"label":"Web users","value":"25,000+","note":"Administrative / clinical users, as reported"},{"label":"Mobile users","value":"10,000+","note":"Patient / provider users, as reported"},{"label":"Clients processed daily","value":"400,000+","note":"Counting unit not defined"}],"related":[{"label":"Research: AI-enabled HMIS evaluation framework","href":"/research/ai-enabled-hmis"},{"label":"Solutions: Healthcare & Enterprise Platforms","href":"/solutions#platforms"}]}', true, 10, '2026-11-13 15:26:06.966193+00', 'admin@arl.local');
INSERT INTO public.content_entries ("Id", "Type", "Slug", "Title", "Data", "IsPublished", "SortOrder", "UpdatedAtUtc", "UpdatedBy") VALUES ('33e75ca3-f29d-4918-8746-c63575a6e406', 'project', 'emr-cct-integration', 'EMR and Conditional Cash Transfer (CCT) Integration', '{"slug":"emr-cct-integration","title":"EMR and Conditional Cash Transfer (CCT) Integration","pillar":"platforms","status":"historical","period":"2021 – 2023","context":"World Bank-supported health programme, Punjab. Individual consultancy (IT Specialist).","summary":"Implementation strategy for an electronic medical record application used to identify eligible households and generate conditional cash transfers in the health sector.","challenge":"Deploy a facility-level EMR across hundreds of facilities, and connect it to government agencies and payment providers so that transfers could reach eligible households reliably.","solution":["Prepared the implementation strategy for EMR deployment across 800+ facilities and 5,000+ end users in 11 districts.","Supported integration with government agencies and payment service providers so the application could generate CCT payments to about 1.4 million eligible households.","Scripted ETL jobs, designed Tableau dashboards and prepared spatio-temporal maps to monitor project performance.","Designed the EMR training programme, a WhatsApp-group support mechanism and a social-mobilisation campaign to bring beneficiaries to nearby facilities.","Defined KPIs for patient load, disease prevalence and supply consumption, available automatically through the system interface, and coordinated tablets, routers and SIMs for 800+ sites."],"capabilities":["EMR rollout strategy","Payment-provider integration","ETL & Tableau dashboards","Spatio-temporal monitoring","Training & support design"],"reported":[{"label":"Facilities","value":"800+"},{"label":"Districts","value":"11"},{"label":"End users","value":"5,000+"},{"label":"Eligible households","value":"~1.4 million"}]}', true, 20, '2026-11-13 15:26:06.973903+00', 'admin@arl.local');
INSERT INTO public.content_entries ("Id", "Type", "Slug", "Title", "Data", "IsPublished", "SortOrder", "UpdatedAtUtc", "UpdatedBy") VALUES ('aca5ac1d-5dd6-408f-9dd0-fa672066be4b', 'project', 'intelligent-file-management', 'Intelligent File Management and Agentic AI', '{"slug":"intelligent-file-management","title":"Intelligent File Management and Agentic AI","pillar":"ai","status":"initiative","period":"2026 – present","context":"Institutional, on-premises workflow initiative.","summary":"An on-premises intelligent file system that runs a local large language model through agentic workflows to prepare cited minutes and draft replies for officer approval.","challenge":"Case files depend on statutes, standing orders and prior precedent. Staff need drafts grounded in the organisation''s own record, with a human officer remaining in control of every decision and outgoing letter.","solution":["Specialist agents use retrieval-augmented generation over statutes, standing orders and closed precedents, then prepare a cited minute and draft the reply letter.","The officer reviews, approves and issues — the system assists, it does not decide.","Each closed file is written back into the RAG library, so later cases are answered from the organisation''s own record.","The workflow is designed to be retargeted to another specialist desk, such as HR, by changing the corpus, officer roles and the rules the agents must follow.","Runs on-premises with a local model, suited to privacy-conscious, offline-first environments."],"capabilities":["Local LLM","RAG with citations","Multi-agent workflow","Human approval stage","Institutional memory"],"related":[{"label":"Solutions: AI & Agentic Systems","href":"/solutions#ai"}]}', true, 30, '2026-11-13 15:26:06.977929+00', 'admin@arl.local');
INSERT INTO public.content_entries ("Id", "Type", "Slug", "Title", "Data", "IsPublished", "SortOrder", "UpdatedAtUtc", "UpdatedBy") VALUES ('5c114601-12c2-41ec-9599-daa349428f5e', 'project', 'oneverse-aios', 'OneVerse AIOS — Enterprise AI Operating Platform', '{"slug":"oneverse-aios","title":"OneVerse AIOS — Enterprise AI Operating Platform","pillar":"ai","status":"initiative","period":"2018 – present","context":"Institutional AI engineering and R&D programme. Design and development: Muhammad Arfan.","summary":"A modular enterprise AI platform that brings Python services, LLM APIs, agent orchestration, knowledge services, retrieval-augmented generation and workflow automation together under human-in-the-loop control.","challenge":"Organisations want to use several models and many internal data sources, but need controlled tool execution, secure access to enterprise information and a human decision-maker in the loop.","solution":["Designed a modular platform integrating Python services, LLM and REST APIs, agent orchestration, knowledge services, RAG and workflow automation.","Developed reusable integration patterns for controlled tool execution, multi-model use and access to enterprise information.","Built in human-in-the-loop controls, input and output validation, access control and regression testing."],"capabilities":["Agent orchestration","Multi-model integration","RAG & knowledge services","Controlled tool execution","Human-in-the-loop","LangChain · LangGraph · CrewAI"],"related":[{"label":"Solutions: AI & Agentic Systems","href":"/solutions#ai"}]}', true, 40, '2026-11-13 15:26:06.981368+00', 'admin@arl.local');
INSERT INTO public.content_entries ("Id", "Type", "Slug", "Title", "Data", "IsPublished", "SortOrder", "UpdatedAtUtc", "UpdatedBy") VALUES ('976d069e-3624-4ea4-a188-a3159a38c39b', 'project', 'ai-document-intelligence', 'AI Document Intelligence', '{"slug":"ai-document-intelligence","title":"AI Document Intelligence","pillar":"ai","status":"initiative","period":"2018 – present","context":"Institutional AI engineering and R&D programme. Design and development: Muhammad Arfan.","summary":"A document-processing pipeline from parsing and OCR through embeddings and hybrid retrieval to source-grounded LLM extraction and summarisation.","challenge":"Information in large document collections is hard to find, and AI-generated answers are only useful if they can be traced back to their source.","solution":["Built a pipeline covering parsing and OCR, chunking, metadata extraction, embeddings, semantic and hybrid retrieval, reranking, and LLM-based extraction and summarisation.","Designed source-grounded output patterns that support traceability and more reliable information discovery.","Uses vector stores such as Qdrant, Chroma and pgvector, with locally hosted models (Ollama, Qwen) where privacy requires."],"capabilities":["OCR & parsing","Hybrid retrieval & reranking","Source-grounded answers","Vector databases","Local LLMs"]}', true, 50, '2026-11-13 15:26:06.985326+00', 'admin@arl.local');
INSERT INTO public.content_entries ("Id", "Type", "Slug", "Title", "Data", "IsPublished", "SortOrder", "UpdatedAtUtc", "UpdatedBy") VALUES ('eca692a6-4f3d-4f80-ae34-b4d22339a0ff', 'project', 'ai-email-hr-quotation-applications', 'AI eMail, HR Management & Quotation Management Applications', '{"slug":"ai-email-hr-quotation-applications","title":"AI eMail, HR Management & Quotation Management Applications","pillar":"ai","status":"initiative","period":"2018 – present","context":"Institutional AI engineering and R&D programme. Design and development: Muhammad Arfan.","summary":"AI-assisted business workflows for email handling, HR policy retrieval and quotation analysis, with controlled data access and user oversight.","challenge":"Routine correspondence, HR queries and quotation comparison consume skilled staff time but still need accuracy and human accountability.","solution":["Designed AI-assisted workflows for email generation and classification, HR policy retrieval, quotation analysis, document processing and structured information extraction.","Integrated application logic with APIs and databases, emphasising controlled data access, output validation and user oversight."],"capabilities":["Email classification & drafting","HR policy retrieval","Quotation analysis","Structured extraction","Output validation"]}', true, 60, '2026-11-13 15:26:06.98846+00', 'admin@arl.local');
INSERT INTO public.content_entries ("Id", "Type", "Slug", "Title", "Data", "IsPublished", "SortOrder", "UpdatedAtUtc", "UpdatedBy") VALUES ('50bdf412-db26-4c1b-9d54-97871b85672c', 'project', 'ai-evaluation-verification-platform', 'Enterprise AI Evaluation & Verification Platform', '{"slug":"ai-evaluation-verification-platform","title":"Enterprise AI Evaluation & Verification Platform","pillar":"ai","status":"poc","period":"2018 – present","context":"Design concept within an institutional AI engineering and R&D programme. Design: Muhammad Arfan.","summary":"A project-level evaluation concept that analyses source repositories for quality and security concerns, supports automated testing and prioritises defects in developer-oriented reports.","challenge":"AI-built and AI-assisted software is often judged on demonstrations. Teams need repeatable verification and evidence-based findings.","solution":["Designed a project-level evaluation workflow for analysing source repositories and identifying quality and security concerns.","Structured the workflow around repeatable verification, evidence-based findings and retesting — not demonstrations alone.","Supports automated testing, defect prioritisation and developer-oriented reporting."],"capabilities":["Automated evaluation","Code quality & security analysis","Regression testing","Defect prioritisation"],"related":[{"label":"Research: responsible AI competence (RAI-ECTF)","href":"/research/rai-ectf"}]}', true, 70, '2026-11-13 15:26:06.991718+00', 'admin@arl.local');
INSERT INTO public.content_entries ("Id", "Type", "Slug", "Title", "Data", "IsPublished", "SortOrder", "UpdatedAtUtc", "UpdatedBy") VALUES ('5a1bce47-a7a8-4d4c-a603-627ae4cf7e1c', 'project', 'data-centre-virtualisation', 'Data-centre Virtualisation and Enterprise IT Services', '{"slug":"data-centre-virtualisation","title":"Data-centre Virtualisation and Enterprise IT Services","pillar":"research","status":"historical","period":"2010 – 2018","context":"Military IT data centres (Senior IT Systems Administrator).","summary":"Administration of enterprise systems for 3,000+ users and a virtualisation programme that consolidated physical servers into a virtual environment.","challenge":"Keep enterprise services available, secure and supportable for thousands of users while reducing ageing hardware.","solution":["Administered Windows Server, Active Directory, Group Policy, DNS/DHCP and file and print services for 3,000+ users.","Supported access control, secure configuration, incident troubleshooting, backup and recovery, monitoring and operational continuity.","Took part in infrastructure modernisation, consolidating 20+ physical servers into a virtualised environment with a reported 25% reduction in hardware costs."],"capabilities":["Windows Server & Active Directory","Virtualisation","Backup & recovery","Secure configuration","Service continuity"],"reported":[{"label":"Users supported","value":"3,000+"},{"label":"Servers consolidated","value":"20+"},{"label":"Hardware cost reduction","value":"25%","note":"As reported"}]}', true, 80, '2026-11-13 15:26:06.995506+00', 'admin@arl.local');
INSERT INTO public.content_entries ("Id", "Type", "Slug", "Title", "Data", "IsPublished", "SortOrder", "UpdatedAtUtc", "UpdatedBy") VALUES ('190c2336-f96f-4e19-a743-26d8cb631b5c', 'project', 'hospital-management-system', 'Hospital Management System Deployment', '{"slug":"hospital-management-system","title":"Hospital Management System Deployment","pillar":"platforms","status":"historical","period":"2014 – 2017","context":"Ministry of Defence hospital programme and CMH Lahore (leadership roles).","summary":"Programme and hospital-level leadership of a large hospital management system rollout, from pilot to deployment across the hospital network.","challenge":"Introduce a hospital management system at scale while keeping hospitals running 24/7, building local capability and reducing dependence on the original vendor.","solution":["Executed the pilot and deployment of the HMS across 61 hospitals; defined strategies, policies and procedures, the supporting IT and network infrastructure, a three-tier 24/7 support model and a stakeholder responsibility matrix.","Planned gradual capacity building and transfer of technology from the vendor.","Ran a post-implementation study and, using user feedback, defined the contours of a new solution, then selected and customised a third-party platform.","As Head of IT at a large military hospital: deployed the pilot, established registration counters and a 24/7 helpline, trained 1,000+ doctors and support personnel, re-engineered business processes and supported information-security and ISO audits."],"capabilities":["Hospital information systems","Rollout programme leadership","Support model design","Training & transfer of technology","Business-process re-engineering"],"reported":[{"label":"Hospitals deployed","value":"61"},{"label":"Staff trained (single hospital)","value":"1,000+"}]}', true, 90, '2026-11-13 15:26:06.998874+00', 'admin@arl.local');
INSERT INTO public.content_entries ("Id", "Type", "Slug", "Title", "Data", "IsPublished", "SortOrder", "UpdatedAtUtc", "UpdatedBy") VALUES ('8ada9147-27eb-4a64-9f48-250982beb76b', 'project', 'inter-hospital-dicom-sharing', 'Inter-hospital DICOM Sharing', '{"slug":"inter-hospital-dicom-sharing","title":"Inter-hospital DICOM Sharing","pillar":"research","status":"poc","period":"2020 – 2021","context":"Architecture and design work within a government software development division.","summary":"Hardware and software architecture for sharing DICOM imaging studies between hospitals, using distributed indexing, caching and storage.","challenge":"Make diagnostic imaging studies discoverable and quickly retrievable across hospitals without moving every study to every site.","solution":["Designed the distributed indexing mechanism that locates studies across participating hospitals.","Designed caching and storage tiers to keep frequently requested studies close to the clinicians who need them.","Defined the hardware/software architecture for secure inter-hospital exchange."],"capabilities":["DICOM","PACS interoperability","Distributed indexing","Caching & storage architecture"],"related":[{"label":"Research themes: medical data interoperability","href":"/research#themes"}]}', true, 100, '2026-11-13 15:26:07.002064+00', 'admin@arl.local');
INSERT INTO public.content_entries ("Id", "Type", "Slug", "Title", "Data", "IsPublished", "SortOrder", "UpdatedAtUtc", "UpdatedBy") VALUES ('84be7cac-b2ae-4a90-a8a1-1ab3379e9b49', 'project', 'gis-trafficability-management', 'GIS Trafficability Management System', '{"slug":"gis-trafficability-management","title":"GIS Trafficability Management System","pillar":"research","status":"historical","period":"2010","context":"GIS consultancy for a national survey organisation.","summary":"A GIS-based system that combines terrain, weather and survey data to plan routes for heavy vehicles through hazardous areas such as marshy and rough terrain.","challenge":"Plan safe movement routes for heavy vehicles where ground conditions change with terrain and weather.","solution":["Designed, developed and deployed the Trafficability Management System.","Built an add-in for QGIS and Geomedia add-ins to support map editing and printing operations.","Developed an interactive digital system mapper for overlay marking.","Carried out feasibility studies and reported progress to senior management."],"capabilities":["GIS decision support","Terrain & weather analysis","QGIS / Geomedia extensions","Route planning"]}', true, 110, '2026-11-13 15:26:07.005881+00', 'admin@arl.local');
INSERT INTO public.content_entries ("Id", "Type", "Slug", "Title", "Data", "IsPublished", "SortOrder", "UpdatedAtUtc", "UpdatedBy") VALUES ('17668da0-eefc-4c57-a46f-7afd56f37674', 'project', 'gis-soil-intelligence-portal', 'GIS Soil Intelligence Portal', '{"slug":"gis-soil-intelligence-portal","title":"GIS Soil Intelligence Portal","pillar":"research","status":"historical","period":"2011","context":"GIS consultancy for a major fertiliser manufacturer.","summary":"Real-time GIS visualisation that replaced reports and charts from an existing BI solution, plus geostatistical soil-fertility maps and an online fertiliser-recommendation portal.","challenge":"Senior executives were overwhelmed by numerous reports, graphs and charts, which slowed decision-making.","solution":["Designed real-time GIS-based visualisation to replace the existing BI dashboards and reports.","Produced geostatistical soil-fertility maps and developed an online portal for fertiliser suggestions.","Ran ETL over twelve years of soil-survey data from five units, and trained staff."],"capabilities":["Geostatistics","Web GIS portal","ETL & data engineering","Executive decision support"]}', true, 120, '2026-11-13 15:26:07.008866+00', 'admin@arl.local');
INSERT INTO public.content_entries ("Id", "Type", "Slug", "Title", "Data", "IsPublished", "SortOrder", "UpdatedAtUtc", "UpdatedBy") VALUES ('82102283-6ff4-4761-b1ab-f9e21167e073', 'project', 'data-centre-modernisation', 'Data-centre Modernisation', '{"slug":"data-centre-modernisation","title":"Data-centre Modernisation","pillar":"research","status":"poc","period":"2020 – 2021","context":"Proof of concept within a government software development division.","summary":"A proof of concept for redesigning IT and network-security infrastructure across multiple data centres.","challenge":"Provision dozens of software services to thousands of users on ageing infrastructure while improving security and reducing hardware dependency.","solution":["Design objectives: improve performance and delivery of existing software services; free up to 50% of servers and network equipment; strengthen overall security; extend the life of existing servers by 8–10 years.","Devised a hardware and software mechanism to connect a highly secure network with the internet safely."],"capabilities":["Data-centre architecture","Network security design","Capacity optimisation","Secure connectivity"]}', true, 130, '2026-11-13 15:26:07.011658+00', 'admin@arl.local');
INSERT INTO public.content_entries ("Id", "Type", "Slug", "Title", "Data", "IsPublished", "SortOrder", "UpdatedAtUtc", "UpdatedBy") VALUES ('326a6659-bdc4-41fb-91a1-876beb4c4109', 'project', 'erp-implementation', 'ERP Implementation', '{"slug":"erp-implementation","title":"ERP Implementation","pillar":"platforms","status":"historical","period":"2023 – 2025","context":"ERP programme for a large government manufacturing organisation (Project Manager).","summary":"Led the implementation team for an enterprise resource planning system, with responsibility for user needs, technical support, cybersecurity and IT operations.","challenge":"Introduce ERP across a large organisation while keeping user issues resolved quickly and operations secure.","solution":["Led the ERP implementation team, gathering user needs and technical-support issues.","Acted as liaison between users, developers and data-centre teams to resolve issues promptly.","Managed cybersecurity and IT operations for the organisation."],"capabilities":["ERP programme management","Requirements & support","Cybersecurity management","IT operations"]}', true, 140, '2026-11-13 15:26:07.0151+00', 'admin@arl.local');
INSERT INTO public.content_entries ("Id", "Type", "Slug", "Title", "Data", "IsPublished", "SortOrder", "UpdatedAtUtc", "UpdatedBy") VALUES ('2e8609db-95a2-4ff1-a848-b76821356748', 'project', 'digital-library-archival-systems', 'Digital Library and Archival Systems', '{"slug":"digital-library-archival-systems","title":"Digital Library and Archival Systems","pillar":"research","status":"historical","period":"2007 – 2014","context":"Government directorate project work.","summary":"Digital library management, public online cataloguing and digital archiving across a network of libraries and an archives department.","challenge":"Modernise library services and preserve archival material, including old newspapers, in digital form.","solution":["Established a digital library management system and supported a network of 60 libraries.","Designed a 3D, publicly accessible online catalogue and supported the redesign of the central library.","Started digital archiving for the archives department and for old newspapers.","Conducted feasibility studies, progress reporting and staff training."],"capabilities":["Digital library systems","Online catalogue design","Digital archiving","Feasibility studies"]}', true, 150, '2026-11-13 15:26:07.018181+00', 'admin@arl.local');
INSERT INTO public.content_entries ("Id", "Type", "Slug", "Title", "Data", "IsPublished", "SortOrder", "UpdatedAtUtc", "UpdatedBy") VALUES ('da907e4d-5b7d-4350-b057-795f2e0e5152', 'project', 'medical-iot-pathology-integration', 'Medical IoT and Pathology-instrument Integration', '{"slug":"medical-iot-pathology-integration","title":"Medical IoT and Pathology-instrument Integration","pillar":"research","status":"poc","period":"2020 – 2021","context":"Proof-of-concept work within a government software development division.","summary":"Proof of concept for IoT-based continuous health monitoring of patients, and design of a hardware device to automate pathology-machine integration.","challenge":"Capture patient vital signs and laboratory-instrument results automatically instead of by manual transcription.","solution":["Conducted a proof of concept for continuous, IoT-based patient health monitoring.","Designed a hardware device to automate integration of pathology machines with information systems."],"capabilities":["Medical IoT","Device integration","Laboratory automation","Connected health"],"related":[{"label":"Research themes: connected diagnostic systems","href":"/research#themes"}]}', true, 160, '2026-11-13 15:26:07.020851+00', 'admin@arl.local');
INSERT INTO public.content_entries ("Id", "Type", "Slug", "Title", "Data", "IsPublished", "SortOrder", "UpdatedAtUtc", "UpdatedBy") VALUES ('83e95c74-2575-4bed-ab6f-999133331c2f', 'project', 'government-enterprise-systems', 'Government Enterprise and Management Systems', '{"slug":"government-enterprise-systems","title":"Government Enterprise and Management Systems","pillar":"platforms","status":"historical","period":"2004 – 2014","context":"Consulting and government assignments, including World Bank and provincial-government programmes.","summary":"Financial, human-resource, logistics and monitoring-and-evaluation systems for public-sector and development programmes.","challenge":"Provide dependable management systems for public bodies and development projects at scale.","solution":["Financial Management System for a World Bank project, now used by 100+ cities in Pakistan.","Human Resource Management System later adopted across government, oil, agri-tech and retail sectors, locally and internationally.","Monitoring and Evaluation systems for a provincial-government project.","Feasibility studies for government HR, financial and logistics management systems."],"capabilities":["Financial management","HRMS","Logistics management","Monitoring & evaluation"],"reported":[{"label":"Cities using the FMS","value":"100+"}]}', true, 170, '2026-11-13 15:26:07.023915+00', 'admin@arl.local');
INSERT INTO public.content_entries ("Id", "Type", "Slug", "Title", "Data", "IsPublished", "SortOrder", "UpdatedAtUtc", "UpdatedBy") VALUES ('a1653d14-2273-4cb0-be26-8974b1f5ecec', 'leader', 'abid-ghaffar', 'Mr. Abid Ghaffar', '{"slug":"abid-ghaffar","initials":"AG","name":"Mr. Abid Ghaffar","role":"Chief Executive Officer","headline":"Technology leader and principal software architect","bio":["Mr. Abid Ghaffar is a technology leader and principal software architect with more than two decades of experience across public health, government, defence-related environments, enterprise systems and international development assignments.","His work spans healthcare information systems, enterprise architecture, high-concurrency software, data engineering, geospatial technologies and AI/LLM-based workflows — including local language models, retrieval-augmented generation and agentic workflows for privacy-conscious, on-premises environments."],"highlights":[{"value":"20+","label":"years of technical leadership"},{"value":"2,000+","label":"sites — provincial HMIS (reported)"},{"value":"25,000+","label":"users — provincial HMIS (reported)"}],"focus":["Healthcare information systems","Enterprise architecture","Local AI & agentic workflows","High-concurrency engineering","GIS & data engineering"],"credentials":["MicroMasters in Data, Economics and Development Policy — Massachusetts Institute of Technology","MS (Computer Science), Data Mining / Business Intelligence — University of Engineering and Technology, Lahore","Certified Professional in Healthcare Information and Management Systems (CPHIMS) — HIMSS","ITIL certified; machine-learning, big-data and cloud certifications"],"work":[{"label":"Provincial HMIS","href":"/projects/provincial-hmis"},{"label":"EMR and CCT Integration","href":"/projects/emr-cct-integration"},{"label":"Intelligent File Management","href":"/projects/intelligent-file-management"}]}', true, 10, '2026-11-13 15:39:43.997034+00', 'admin@arl.local');
INSERT INTO public.content_entries ("Id", "Type", "Slug", "Title", "Data", "IsPublished", "SortOrder", "UpdatedAtUtc", "UpdatedBy") VALUES ('e2ab8421-7b03-4100-ad2e-747f341cd126', 'leader', 'muhammad-arfan', 'Mr. Muhammad Arfan', '{"slug":"muhammad-arfan","initials":"MA","name":"Mr. Muhammad Arfan","role":"Director, Operations & Research","headline":"AI architect, enterprise-systems engineer and researcher","bio":["Mr. Muhammad Arfan leads operations and research at Agentic Research Labs. A software-engineering graduate with more than sixteen years of experience, he combines enterprise-scale IT operations — application infrastructure, cybersecurity and service continuity for thousands of users — with hands-on AI engineering.","He designs AI-enabled applications and enterprise integrations: LLM integration, retrieval-augmented generation, agent orchestration with human-in-the-loop controls, and automated evaluation and verification. He applies software-engineering discipline — input and output validation, regression testing, access control and documentation — so that AI systems are maintainable, secure and trustworthy in production.","As Director, Operations & Research he connects applied research and technical design with operational planning, delivery coordination and institutional requirements. His research at Agentic Research Labs addresses responsible AI governance and measurable ethical competence, and the evaluation of AI-enabled health information systems."],"highlights":[{"value":"16+","label":"years across enterprise IT and AI"},{"value":"3,000+","label":"users supported by services he administered"},{"value":"20+","label":"physical servers consolidated through virtualisation"},{"value":"25%","label":"reported hardware-cost reduction"}],"focus":["Operations & delivery coordination","AI engineering & research","LLM, RAG & agent orchestration","Secure infrastructure","Systems integration","Responsible AI governance"],"expertise":[{"group":"AI engineering","items":["LLM integration","RAG & hybrid retrieval","Agent orchestration (LangChain, LangGraph, CrewAI)","Local models (Ollama, Qwen)","Vector stores (Qdrant, Chroma, pgvector)","Automated evaluation"]},{"group":"Software & integration","items":["Python","C# / .NET","SQL","PowerShell","REST & Web APIs","Workflow automation"]},{"group":"Enterprise & Microsoft","items":["Windows Server","Active Directory & Group Policy","Microsoft 365 / Azure fundamentals","DNS / DHCP","File & print services"]},{"group":"Security & operations","items":["RBAC, MFA, SSO, OAuth","TLS & endpoint security","Backup & recovery","Monitoring","Technical documentation"]}],"career":[],"credentials":["Bachelor of Software Engineering — GC University, Faisalabad (2005–2009)","Google Project Management certificate","Microsoft Azure Fundamentals (AZ-900); 38 Microsoft Learn certified badges","Anthropic AI Fluency: Framework Foundations; Claude Code 101; Claude Code in Action"],"work":[{"label":"OneVerse AIOS","href":"/projects/oneverse-aios"},{"label":"AI Document Intelligence","href":"/projects/ai-document-intelligence"},{"label":"AI eMail, HR & Quotation applications","href":"/projects/ai-email-hr-quotation-applications"},{"label":"AI Evaluation & Verification Platform","href":"/projects/ai-evaluation-verification-platform"},{"label":"Data-centre Virtualisation","href":"/projects/data-centre-virtualisation"},{"label":"Research: RAI-ECTF — measurable ethical competence","href":"/research/rai-ectf"},{"label":"Research: AI-enabled HMIS","href":"/research/ai-enabled-hmis"}]}', true, 20, '2026-11-13 15:40:36.543612+00', 'admin@arl.local');


